import collections

def check_connectivity(S, B, k):
    """
    Builds the graph for a single merchant and returns connected components.
    Nodes are indexed by (type, index). Type 0=S, 1=B.
    """
    nodes = {}
    for i in range(k):
        nodes[f'S_{i}'] = S[i]
        nodes[f'B_{i}'] = B[i]

    graph = collections.defaultdict(list)

    # Edges: S_i -> B_j if S_i < B_j
    for i in range(k):
        for j in range(k):
            if S[i] < B[j]:
                graph[f'S_{i}'].append(f'B_{j}')

    # Edges: B_j -> S_l if B_j < S_l
    for j in range(k):
        for l in range(k):
            if B[j] < S[l]:
                graph[f'B_{j}'].append(f'S_{l}')

    return graph, nodes

def get_components(graph, nodes):
    """Finds all connected components using BFS/DFS."""
    visited = set()
    components = []

    for node in nodes.keys():
        if node not in visited:
            component = set()
            queue = collections.deque([node])
            visited.add(node)
            component.add(node)

            while queue:
                u = queue.popleft()
                for v in graph.get(u, []):
                    if v not in visited:
                        visited.add(v)
                        component.add(v)
                        queue.append(v)
            components.append(component)
    return components

def has_shared_connected_pair(S_A, B_A, S_B, B_B, k):
    """Checks if there is a pair of distinct stalls connected by both A and B."""

    # 1. Build components for A and B
    graph_A, nodes_A = check_connectivity(S_A, B_A, k)
    components_A = get_components(graph_A, nodes_A)

    graph_B, nodes_B = check_connectivity(S_B, B_B, k)
    components_B = get_components(graph_B, nodes_B)

    # Map node (string label) to its component ID
    comp_map_A = {}
    for idx, comp in enumerate(components_A):
        for node in comp:
            comp_map_A[node] = idx

    comp_map_B = {}
    for idx, comp in enumerate(components_B):
        for node in comp:
            comp_map_B[node] = idx

    # 2. Check pairs (V1, V2)
    all_nodes = list(nodes_A.keys())

    for i in range(len(all_nodes)):
        for j in range(i + 1, len(all_nodes)):
            node1 = all_nodes[i]
            node2 = all_nodes[j]

            # Check if nodes are in the same component for A
            if node1 in comp_map_A and node2 in comp_map_A and comp_map_A[node1] == comp_map_A[node2]:

                # Check if nodes are in the same component for B
                if node1 in comp_map_B and node2 in comp_map_B and comp_map_B[node1] == comp_map_B[node2]:
                    return True, (node1, node2) # Success

    return False, None # Failure

